#include <stdio.h>
typedef struct R { unsigned int lane, quorum, frontier; int delta; } R;
typedef struct A { unsigned int quorum[5], frontier[5]; int value[5]; } A;
static unsigned int mix(unsigned int h,unsigned int v){ h ^= v + 0x9e3779b9u + (h<<6) + (h>>2); return h; }
static void clear(A* a){ for(int i=0;i<5;++i){ a->quorum[i]=0u; a->frontier[i]=0u; a->value[i]=0; } }
static void absorb(A* a,const R* r){ unsigned int lane=r->lane%5u; if(r->quorum<a->quorum[lane]) return; if(r->quorum>a->quorum[lane]){ a->quorum[lane]=r->quorum; a->frontier[lane]=r->frontier; a->value[lane]=r->delta; return; } if(r->frontier>a->frontier[lane]){ a->frontier[lane]=r->frontier; a->value[lane]=r->delta; } else if(r->frontier==a->frontier[lane]) a->value[lane]+=r->delta; }
static unsigned int sig(const A* a){ unsigned int h=2166136261u; for(unsigned int lane=0; lane<5u; ++lane){ h=mix(h,lane+1u); h=mix(h,a->quorum[lane]); h=mix(h,a->frontier[lane]); h=mix(h,(unsigned int)(a->value[lane]&0xffff)); } return h; }
int main(void){ const R rows[]={{0u,2u,1u,4},{1u,3u,2u,5},{2u,1u,3u,7},{3u,2u,4u,3},{4u,1u,2u,6},{0u,5u,2u,6},{1u,4u,3u,-1},{2u,5u,2u,8},{3u,4u,5u,2},{4u,5u,3u,4},{0u,5u,2u,-2},{1u,4u,3u,4},{2u,5u,4u,1},{3u,4u,5u,-3},{4u,5u,3u,-1},{0u,6u,4u,5},{1u,6u,5u,3},{2u,6u,4u,6},{3u,6u,6u,1},{4u,6u,2u,2}}; A d,p; clear(&d); for(unsigned int i=0;i<sizeof(rows)/sizeof(rows[0]);++i) absorb(&d,&rows[i]); clear(&p); for(unsigned int quorum=1u; quorum<=6u; ++quorum) for(unsigned int frontier=1u; frontier<=6u; ++frontier) for(unsigned int lane=0; lane<5u; ++lane){ int merged=0,saw=0; for(unsigned int i=0;i<sizeof(rows)/sizeof(rows[0]);++i){ if(rows[i].lane%5u!=lane || rows[i].quorum!=quorum || rows[i].frontier!=frontier) continue; merged+=rows[i].delta; saw=1; } if(saw){ R row={lane,quorum,frontier,merged}; absorb(&p,&row); } } { unsigned int sd=sig(&d), sp=sig(&p); printf("%u %u %u\n", sd, sp, (sd==sp)?1u:0u); } return 0; }
